// LAB: Reject an incomplete pipeline before launching it
// Parse a deliberately small grammar: word, pipe, word, separated by spaces. Reject missing stages, extra words, and multiple pipes. This parser has no quotes, expansions, or redirection.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

int main() {
    const std::string line = "emit | count";
    std::istringstream input(line);
    std::vector<std::string> tokens;
    for (std::string word; input >> word;) tokens.push_back(word);
    assert(tokens.size() == 3 && tokens[1] == "|");
    std::cout << "left=" << tokens[0] << " right=" << tokens[2] << '\n';
}

#include <cassert>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>
#include <utility>

std::optional<std::pair<std::string,std::string>> parse(const std::string& line) {
    std::istringstream input(line);
    std::string left, pipe, right, extra;
    if(!(input >> left >> pipe >> right) || input >> extra) return std::nullopt;
    if(pipe != "|" || left == "|" || right == "|") return std::nullopt;
    return std::pair<std::string,std::string>{left,right};
}

int main() {
    const auto good = parse("emit | count");
    assert(good && good->first == "emit" && good->second == "count");
    assert(!parse("emit |") && !parse("| count"));
    assert(!parse("emit | count extra") && !parse("a | b | c"));
    std::cout << "left=" << good->first << " right=" << good->second << " invalid=rejected\n";
}

